/* ===== Writer E — romance lines: lucia jolene savannah clara hannah brooke megan colleen ===== */
const rE_busy=()=>[12,24,36,48].includes(S.week)||S.week>=49;
const rE_free=id=>!S.settled||S.settled===id;
const rE_T=id=>()=>rel(id).truth===true||NEED(t('真话时刻','Moment of truth','Momento da verdade'));
const rE_ST=(k,n)=>()=>S.stats[k]>=n||NEED(t({charme:'魅力',oficio:'手艺',tex:'德州味',saud:'乡愁'}[k]+' '+n,{charme:'Charm',oficio:'Craft',tex:'Texanness',saud:'Homesickness'}[k]+' '+n,{charme:'Charme',oficio:'Ofício',tex:'Texanidade',saud:'Saudade'}[k]+' '+n));
const rE_CO=(k,n)=>()=>S.course[k]>=n||NEED(t({drive:'开车',ride:'骑马'}[k]+' '+n,{drive:'Driving',ride:'Riding'}[k]+' '+n,{drive:'Condução',ride:'Equitação'}[k]+' '+n));
const rE_sg=n=>(n>0?'+':'')+n;
const rE_fx=(l,tr)=>[l?t('好感 '+rE_sg(l),'Affection '+rE_sg(l),'Afeto '+rE_sg(l)):'',tr?t('信任 '+rE_sg(tr),'Trust '+rE_sg(tr),'Confiança '+rE_sg(tr)):''].filter(Boolean).join(' · ');
const rE_DM=id=>t('约会','Date','Encontro')+' · '+NM(id);
const rE_CM=id=>t('关系危机','Crisis','Crise')+' · '+NM(id);
const rE_dateWhen=(id,wk,d,s)=>()=>!!(rel(id).met&&rel(id).like>=4&&rel(id).trust>=3&&S.week>=wk&&S.day===d&&S.slot===s&&!rE_busy()&&rE_free(id));
const rE_crisisWhen=(id,wk,d,s)=>()=>!!(rel(id).truth===true&&S.week>20&&S.week>=wk&&S.day===d&&S.slot===s&&!rE_busy()&&rE_free(id));

Object.assign(ROMX,{
 lucia:{beats:[
  t(`她带你去看牧场南边那口封起来的旧井。“爸爸二十年前就不让牛喝这里的水了。他不肯说为什么。”`,`She takes you to the capped old well on the south pasture. "Dad stopped letting the cattle drink here twenty years ago. He won't say why."`,`Leva-te ao poço velho e tapado do pasto sul. «O meu pai deixou de dar esta água às vacas há vinte anos. Não diz porquê.»`),
  t(`一头小牛难产，她整条胳膊伸进去，你按住母牛的头。结束后她满身是血地笑：“你没晕。我记下了。”`,`A calf comes out wrong. She goes in up to the shoulder while you hold the cow's head. Afterward, bloody to the elbows, she grins. "You didn't faint. I'm writing that down."`,`Um vitelo está mal virado. Ela mete o braço até ao ombro enquanto tu seguras a cabeça da vaca. No fim, ensanguentada, sorri: «Não desmaiaste. Vou tomar nota.»`),
  t(`她第一次没叫你“城里人”，而是叫了你的名字。叫得很轻，像在试一把新钥匙。`,`For the first time she doesn't call you "city boy." She says your name instead, quietly, like she's trying a new key in a lock.`,`Pela primeira vez não te chama «menino da cidade». Diz o teu nome, baixinho, como quem experimenta uma chave nova.`),
  t(`她翻出若泽写给贝托的一张借条：三百块，从没还过，也从没被催过。“爸爸说那是买沉默的钱，”她说，“买的是他自己的沉默。”`,`She digs out an IOU José wrote to Beto: three hundred dollars, never repaid, never asked for. "Dad says it was hush money," she says. "Paying for his own silence."`,`Encontra um vale que o José passou ao Beto: trezentos dólares, nunca pagos, nunca cobrados. «O meu pai diz que foi dinheiro para calar», diz ela. «Para calar o silêncio dele.»`)],
  epilogue:t(`一年后，雷耶斯牧场南井的水终于验出干净。露西娅在井边钉了一张双人长凳，说是“给城里人歇脚的”。`,`A year on, the south well at the Reyes ranch finally tests clean. Lucía nails together a two-seat bench beside it — "for city boys to rest their legs."`,`Um ano depois, a água do poço do sul do Rancho Reyes vem finalmente limpa nas análises. A Lucía prega um banco de dois lugares ao lado — «para os meninos da cidade descansarem».`)},
 jolene:{beats:[
  t(`她问你法多是什么。你哼了两句，她说：“那不就是乡村音乐吗？丢了的东西，喝多了的夜。”`,`She asks what fado is. You hum a couple of lines. "So it's country music," she says. "Stuff you lost. Nights you drank too much."`,`Pergunta-te o que é o fado. Trauteias dois versos. «Então é música country», diz ela. «Coisas que se perderam. Noites em que se bebeu demais.»`),
  t(`厄尔不在的时候，她说起她妈：十九岁去了纳什维尔，三年后挺着肚子回来。“所以爷爷每次听我说走，都假装没听见。”`,`While Earl's out, she tells you about her mom: went to Nashville at nineteen, came back three years later, pregnant. "So every time I say I'm leaving, Grandpa pretends he didn't hear."`,`Quando o Earl sai, fala-te da mãe: foi para Nashville aos dezanove e voltou três anos depois, grávida. «Por isso, sempre que digo que me vou embora, o avô finge que não ouviu.»`),
  t(`她把一首新歌的第一段写在餐巾纸上给你，里面有一句“他说话像退潮”。她说那句不是写你的。是写你的。`,`She writes the first verse of a new song on a napkin for you. One line says "he talks like the tide going out." She says it isn't about you. It is.`,`Escreve-te num guardanapo a primeira estrofe de uma canção nova. Há um verso que diz «ele fala como a maré a baixar». Diz que não é sobre ti. É.`),
  t(`她攒的钱放在一个咖啡罐里，罐底压着厄尔年轻时在越南的照片。“他没去成他想去的地方，”她说，“我得替他走远一点。”`,`She keeps her savings in a coffee can, with a photo of young Earl in Vietnam at the bottom. "He never got to go where he wanted," she says. "I've got to go a little further for him."`,`Guarda as poupanças numa lata de café, com uma fotografia do Earl novo no Vietname lá no fundo. «Ele nunca foi aonde queria», diz ela. «Tenho de ir um bocadinho mais longe por ele.»`)],
  epilogue:t(`一周年那晚，乔琳的样带里有一首《圣鲁伊斯的退潮》，厄尔在吧台上放了十一遍。你们的约定没变：谁也不劝谁留，谁也不劝谁走。`,`On the anniversary night, Jolene's first Nashville demo has a song called "Low Tide in San Luís," and Earl plays it eleven times behind the bar. Your deal is the same as ever: nobody talks anybody into staying, nobody talks anybody into leaving.`,`Na noite do aniversário, a primeira maqueta da Jolene em Nashville tem uma canção chamada «Maré Baixa em San Luís», e o Earl põe-na onze vezes no bar. O vosso acordo continua o mesmo: ninguém convence ninguém a ficar, ninguém convence ninguém a partir.`)},
 savannah:{beats:[
  t(`她教你给玫瑰去刺，刀要往外推。“别往自己身上拉。我花了十年才学会。”`,`She shows you how to strip thorns off a rose: push the knife away. "Never pull it toward yourself. Took me ten years to learn that."`,`Ensina-te a tirar os espinhos às rosas: a faca empurra-se para fora. «Nunca para o teu lado. Levei dez anos a aprender.»`),
  t(`一辆警车在花店门口停了很久，没人下来。她不抬头：“他就是想让我知道他在。”`,`A patrol car idles outside the flower shop a long time. Nobody gets out. She doesn't look up. "He just wants me to know he's there."`,`Um carro da polícia fica muito tempo parado à porta da florista. Ninguém sai. Ela não levanta os olhos. «Só quer que eu saiba que ele está ali.»`),
  t(`她第一次说起离婚：不是因为他动手，是因为他从不问她想要什么。“十二年，他一次也没问过我喜欢什么花。”`,`For the first time she talks about the divorce. It wasn't his hands — it was that he never asked what she wanted. "Twelve years. Not once did he ask what flower I like."`,`Pela primeira vez fala do divórcio. Não foi por ele lhe bater — foi por nunca lhe perguntar o que ela queria. «Doze anos. Nem uma vez me perguntou de que flor gosto.»`),
  t(`她后院种了一排阿尔贝蒂娜太太分来的亚速尔薰衣草。“我想看看你们那边的东西，能不能在这儿活下来。”`,`Out back she's planted a row of lavender, cuttings Dona Albertina brought from the old Azorean stock. "I want to see if something from your side of the water can make it here."`,`No quintal plantou uma fila de alfazema, de estacas que a Dona Albertina trouxe da variedade açoriana. «Quero ver se uma coisa do teu lado do mar consegue viver aqui.»`)],
  epilogue:t(`一年后，花店后院的薰衣草开了第二茬。你每周五还给萨凡纳送猪排包，像若泽从前那样——只是现在你会留下来，一起吃。`,`A year on, the lavender out back is blooming for the second time. Every Friday you still bring Savannah a pork sandwich the way José did — except now you stay and eat it with her.`,`Um ano depois, a alfazema do quintal floresce pela segunda vez. Às sextas continuas a levar uma bifana à Savannah, como o José fazia — só que agora ficas e comes com ela.`)},
 clara:{beats:[
  t(`她在借书卡背面抄了一句佩索阿：“我什么也不是。我永远不会是什么。”下面用铅笔补了一行：“但我是图书馆员。”`,`On the back of a library card she's copied Pessoa: "I am nothing. I shall never be anything." Below it, in pencil: "But I am a librarian."`,`No verso de uma ficha de requisição copiou Pessoa: «Não sou nada. Nunca serei nada.» Por baixo, a lápis: «Mas sou bibliotecária.»`),
  t(`她给你看她的护照——空白的，十年有效，只剩两年。“办下来那天我喝了半瓶酒庆祝，然后再也没用过。”`,`She shows you her passport: blank, valid ten years, two left. "The day it came I drank half a bottle of wine to celebrate. Never used it once."`,`Mostra-te o passaporte: em branco, válido por dez anos, faltam dois. «No dia em que chegou bebi meia garrafa de vinho para celebrar. Nunca o usei.»`),
  t(`她请你教她那个没法翻译的葡语词——“思念”。她练了二十遍，终于说对了，然后哭了，说只是因为发音太难。`,`She asks you to teach her the Portuguese word nobody can translate — the one for missing. She tries twenty times, finally gets it right, and cries. She says it's only because the vowels are hard.`,`Pede-te que lhe ensines a palavra que ninguém consegue traduzir — saudade. Tenta vinte vezes, finalmente acerta, e chora. Diz que é só porque as vogais são difíceis.`),
  t(`她承认她爱的里斯本有一半是从书里编出来的。“阿尔法马的楼梯到底有多陡？”你说：陡到你妈每次爬上去都要停下来骂一次市长。`,`She admits half the Lisbon she loves she made up out of books. "How steep are the Alfama stairs, really?" Steep enough, you tell her, that your mother stops halfway every time to curse the mayor.`,`Confessa que metade da Lisboa que ama foi inventada a partir de livros. «Quão íngremes são mesmo as escadas de Alfama?» Tanto, dizes-lhe, que a tua mãe pára a meio todas as vezes para rogar pragas ao presidente da câmara.`)],
  epilogue:t(`第二年夏天，克拉拉去了里斯本，从阿尔法马寄来明信片：“楼梯比你说的还陡。你妈妈请我喝了咖啡，一起骂了市长。”九月她回到圣鲁伊斯，带着一本不再空白的护照。`,`The next summer Clara finally goes to Lisbon. A postcard comes from Alfama: "The stairs are steeper than you said. Your mother bought me a coffee and we cursed the mayor together." In September she comes back to San Luís with a passport that isn't blank anymore.`,`No verão seguinte a Clara vai finalmente a Lisboa. Chega um postal de Alfama: «As escadas são mais íngremes do que disseste. A tua mãe pagou-me um café e rogámos pragas ao presidente da câmara juntas.» Em setembro volta a San Luís com um passaporte que já não está em branco.`)},
 hannah:{beats:[
  t(`“我在这儿第一年，没有一个病人叫过我的名字，”她说，“都叫我‘那个北方来的’。”`,`"My first year here, not one patient called me by my name," she says. "I was just 'that Yankee doctor.'"`,`«No meu primeiro ano aqui, nenhum doente me tratou pelo nome», diz ela. «Era só "a médica do Norte".»`),
  t(`她教你在电话里问医生：先问最坏的，再问最可能的。“家属总是反过来，所以总是最后知道。”`,`She teaches you how to talk to a doctor on the phone: ask for the worst first, then the most likely. "Families always do it backwards. That's why they're the last to know."`,`Ensina-te a falar com um médico ao telefone: primeiro pergunta-se o pior, depois o mais provável. «As famílias fazem sempre ao contrário. Por isso são as últimas a saber.»`),
  t(`她说她也有一个没回去的家：父亲在明尼苏达的养老院，已经认不出她了。“我每周打一次电话。他每次都很有礼貌地问我是谁。”`,`She has a home she doesn't go back to, too: her father in a Minnesota care home, who no longer knows her. "I call every week. Every time, he very politely asks who I am."`,`Ela também tem uma casa para onde não volta: o pai num lar no Minnesota, que já não a reconhece. «Ligo todas as semanas. E todas as vezes ele pergunta, muito educado, quem sou eu.»`),
  t(`半夜诊所的灯还亮着。她在给一个没有保险的牧工缝针，收费单上写着：“一盒蛋挞，交给若泽烧烤店。”`,`The clinic light is still on at midnight. She's stitching up an uninsured ranch hand, and on the bill she's written: "One box of custard tarts, payable at Zé's."`,`À meia-noite a luz do consultório ainda está acesa. Ela cose um vaqueiro sem seguro e na fatura escreve: «Uma caixa de pastéis de nata, a pagar no Zé's.»`)],
  epilogue:t(`一周年那天，汉娜戒了那根“不算数”的烟，换成每晚来你店里喝一碗羽衣甘蓝汤。至少现在，病人们都叫她的名字了。`,`On the anniversary Hannah quits the cigarette that "doesn't count" and trades it for a bowl of kale soup at your place every night. At least the patients all call her by her name now.`,`No aniversário a Hannah deixa o cigarro que «não conta» e troca-o por uma tigela de caldo verde na tua casa todas as noites. Pelo menos agora os doentes tratam-na pelo nome.`)},
 brooke:{beats:[
  t(`她的马叫“葡萄干”，因为生下来又黑又皱。“它比我谈过的任何一个男人都靠得住。”`,`Her horse is called Raisin, because he came out dark and wrinkly. "More reliable than any man I ever dated."`,`O cavalo dela chama-se Passa, porque nasceu escuro e enrugado. «Mais fiável do que qualquer homem com quem saí.»`),
  t(`她拖车里钉着一张没有名次的号码布：“第一次参赛，摔断了锁骨。留着提醒我。”`,`Pinned up in her trailer is a number bib with no placing. "First race. Broke my collarbone. Keeps me honest."`,`No atrelado tem pregado um dorsal sem classificação. «Primeira prova. Parti a clavícula. Lembra-me quem sou.»`),
  t(`她在地图上圣鲁伊斯那一点，第一次画了个圈，而不是一个叉。“叉是去过。圈是……还想回来。”`,`On her map, over the dot for San Luís, she draws a circle for the first time instead of a cross. "Cross means been there. Circle means… want to come back."`,`No mapa, sobre o ponto de San Luís, desenha pela primeira vez um círculo em vez de uma cruz. «Cruz é já lá estive. Círculo é… quero voltar.»`),
  t(`凌晨的服务区里，她承认她不是爱路，是怕停下来。“我爸停下来过一次。停在一个镇子里，一张沙发上，停了十五年。”`,`At a truck stop before dawn she admits it isn't the road she loves — it's that she's scared of stopping. "My daddy stopped once. In one town, on one couch. For fifteen years."`,`Numa área de serviço de madrugada confessa que não é a estrada que ama — é medo de parar. «O meu pai parou uma vez. Numa terra, num sofá. Durante quinze anos.»`)],
  epilogue:t(`布鲁克没有停下来，你也没让她停。每年巡回赛的空档，她和葡萄干都回圣鲁伊斯过冬。地图上那个圈，快被她描穿了。`,`Brooke never stopped, and you never asked her to. Every off-season she and Raisin come home to winter in San Luís. The circle on her map is nearly worn through.`,`A Brooke nunca parou, e tu nunca lho pediste. Em cada pausa do circuito ela e o Passa voltam para passar o inverno em San Luís. O círculo no mapa está quase a rasgar.`)},
 megan:{beats:[
  t(`唱诗班的乐谱页边，写满了她自己改的和声。“爸爸不知道。他以为大家都是照着谱唱的。”`,`The margins of her choir music are full of harmonies she rewrote herself. "Daddy doesn't know. He thinks everybody sings what's printed."`,`As margens das pautas do coro estão cheias de harmonias que ela reescreveu. «O meu pai não sabe. Acha que toda a gente canta o que está impresso.»`),
  t(`她说她当年考上了休斯敦的音乐学院，没去。“那年爸爸刚当上镇议员。他说，一家人要站在一起。”`,`She got into a music conservatory in Houston once. Didn't go. "That was the year Daddy got on the council. He said a family stands together."`,`Uma vez entrou num conservatório em Houston. Não foi. «Foi o ano em que o meu pai entrou para a câmara. Disse que uma família se mantém unida.»`),
  t(`她第一次在你店里堂食，坐在主街谁都看得见的窗边。吃完她手在抖：“下次我还坐这儿。”`,`For the first time she eats in at your place — window seat, where all of Main Street can see. Her hands are shaking after. "Next time I'm sitting here again."`,`Pela primeira vez come na tua casa — à janela, onde toda a rua principal a vê. No fim as mãos tremem-lhe. «Para a próxima sento-me outra vez aqui.»`),
  t(`她告诉你，戴尔牧师年轻时酗酒，是她妈妈把他拉回来的。“所以他怕的不是你的酒，”她说，“是他自己。”`,`She tells you Pastor Dale drank hard when he was young, and it was her mother who pulled him back. "So it's not your liquor he's scared of," she says. "It's himself."`,`Conta-te que o Pastor Dale bebia muito em novo e que foi a mãe dela quem o salvou. «Por isso não é do teu álcool que ele tem medo», diz ela. «É dele próprio.»`)],
  epilogue:t(`梅根秋天去了休斯敦读音乐学院，晚了七年。戴尔牧师来店里吃过一次饭，临走说：“照顾好她。”——这是他最接近祝福的话。`,`In the fall Megan goes to Houston, to the conservatory, seven years late. Pastor Dale eats at Zé's once, and on his way out says, "Take care of her." It's the closest thing to a blessing he's ever given.`,`No outono a Megan vai para Houston, para o conservatório, com sete anos de atraso. O Pastor Dale come lá uma vez e à saída diz-te: «Cuida dela.» É o mais parecido com uma bênção que alguma vez deu.`)},
 colleen:{beats:[
  t(`她的笔记本封面上写着：“不要相信任何人，包括我。”她说是祖父教的，他当了三十年工头。`,`The cover of her notebook says DON'T TRUST ANYBODY, INCLUDING ME. Her grandfather taught her that, she says. Thirty years a foreman.`,`Na capa do caderno dela lê-se: NÃO CONFIES EM NINGUÉM, NEM EM MIM. Foi o avô que lhe ensinou, diz. Trinta anos de capataz.`),
  t(`她带你去看报社地下室的缩微胶片。1998 年那一卷不见了，借阅卡上的名字被人涂掉了。`,`She takes you down to the newspaper's microfilm in the basement. The 1998 reel is missing, and the name on the checkout card has been blacked out.`,`Leva-te à cave do jornal, aos microfilmes. Falta a bobina de 1998, e o nome na ficha de requisição foi riscado.`),
  t(`她带你去疗养院见祖父。老菲茨杰拉德盯着你看了很久：“你长得不像他。但你站的样子像。”`,`She takes you to the nursing home to meet her grandfather. Old Man Fitzgerald stares at you a long while. "You don't look like him. But you stand like him."`,`Leva-te ao lar para conheceres o avô. O velho Fitzgerald fica muito tempo a olhar para ti. «Não és parecido com ele. Mas estás de pé como ele.»`),
  t(`她报道的最后一版删掉了所有夸你长相的句子。“那些是真的，但不重要。剩下的才是你。”`,`In the final draft of her story about you, every line about your looks is gone. "Those were true, but they didn't matter. What's left is you."`,`Na versão final da reportagem sobre ti, cortou todas as frases sobre a tua cara. «Eram verdade, mas não importavam. O que sobra és tu.»`)],
  epilogue:t(`一周年那天，老菲茨杰拉德坐着轮椅来店里吃完一份烤沙丁鱼，说若泽的手艺你学到了七成。科琳在本子上记下“七成”，旁边补了一句：“剩下三成是他自己的。”`,`On the anniversary Old Man Fitzgerald rolls into your place in his wheelchair, finishes a plate of grilled sardines, and says you've got about seventy percent of José's touch. Colleen writes down "seventy percent," then adds beside it: "The other thirty is his own."`,`No aniversário, o velho Fitzgerald entra na tua casa de cadeira de rodas, come um prato de sardinhas assadas e diz que tens uns setenta por cento da mão do José. A Colleen aponta «setenta por cento» e escreve ao lado: «Os outros trinta são dele.»`)}
});

STORY.push(
/* ---------------- LUCÍA ---------------- */
{id:'rE_lucia_date',when:rE_dateWhen('lucia',8,5,2),run:()=>({title:t('谷仓舞会','Barn dance','Baile no celeiro'),meta:rE_DM('lucia'),text:[
  t(`周五夜里，雷耶斯家的谷仓挂起彩灯。露西娅换了靴子——换成一双更旧的。`,`Friday night the Reyes barn is strung with lights. Lucía has traded her work boots for a pair that's even older.`,`Sexta à noite o celeiro dos Reyes está cheio de luzes. A Lucía trocou as botas de trabalho por umas ainda mais velhas.`),
  t(`“两步舞，”她伸出手，“会吗？不会就别踩我。”`,`"Two-step," she says, holding out a hand. "You know it? If not, don't step on me."`,`«Two-step», diz, a estender a mão. «Sabes? Se não sabes, não me pises.»`)],choices:[
  {t:t('让她教你，踩了三次','Let her teach you; step on her three times','Deixá-la ensinar-te; pisá-la três vezes'),fx:()=>{addLike('lucia',1);stat('tex',3)},next:()=>say(t('谷仓舞会','Barn dance','Baile no celeiro'),[t(`第三次她不骂了，只是笑：“城里人，你数拍子的样子像在念经。”`,`By the third time she quits cussing and just laughs. "City boy, you count the beat like you're saying the rosary."`,`À terceira já não pragueja, só se ri. «Menino da cidade, contas os tempos como quem reza o terço.»`)],rE_fx(1,0))},
  {t:t('[德州味] 你早就偷偷学会了，带她转圈','[Texan] You learned in secret — spin her','[Texano] Aprendeste às escondidas — fá-la rodar'),req:rE_ST('tex',40),fx:()=>{addLike('lucia',2);addTrust('lucia',1)},next:()=>say(t('谷仓舞会','Barn dance','Baile no celeiro'),[t(`转到第四圈，她才反应过来：“谁教你的？”“玛丽索尔。在厨房里。用一把扫帚。”`,`Four turns in she finally catches on. "Who taught you?" "Marisol. In the kitchen. With a broom."`,`À quarta volta é que percebe. «Quem te ensinou?» «A Marisol. Na cozinha. Com uma vassoura.»`)],rE_fx(2,1))},
  {t:t('带她走出谷仓，问起那口井','Walk her outside and ask about the well','Levá-la lá para fora e perguntar pelo poço'),req:rE_T('lucia'),fx:()=>{addTrust('lucia',2);S.flags.rE_lucia_well=1;log('露西娅讲了南井的事','Lucía told you about the south well','A Lucía falou-te do poço do sul')},next:()=>say(t('南边的井','The south well','O poço do sul'),[t(`她靠着栅栏，很久才开口：“我八岁那年，南边死了三头牛。从那以后，爸爸就不许我们在饭桌上提罐头厂。”`,`She leans on the fence a long time before she speaks. "When I was eight, three cows died down south. After that Dad wouldn't let anybody say 'cannery' at the table."`,`Encosta-se à cerca muito tempo antes de falar. «Quando eu tinha oito anos morreram três vacas lá no sul. Depois disso o pai nunca mais deixou ninguém dizer "fábrica" à mesa.»`)],rE_fx(0,2))},
  {t:`[${faceWord()}] `+t('跳慢舞时贴得很近','Hold her close on the slow one','Dançar muito juntinho na lenta'),req:CHARM_REQ(50),fx:()=>{addLike('lucia',2);flirt();addTrust('beto',-1)},next:()=>say(t('谷仓舞会','Barn dance','Baile no celeiro'),[t(`音乐停了。贝托在谷仓门口看了你很久。露西娅脸红了，但不是因为你。`,`The music stops. From the barn door, Beto looks at you a long time. Lucía goes red, and not because of you.`,`A música pára. À porta do celeiro, o Beto fica a olhar para ti muito tempo. A Lucía cora, e não é por tua causa.`)],rE_fx(2,0))}]})},
{id:'rE_lucia_crisis',when:rE_crisisWhen('lucia',37,2,1),run:()=>{const w=S.flags.canneryWith;
 const why=w==='beto'?t(`那晚你带她爸爸去了罐头厂。贝托六十岁了，回来咳了三天。她今天早上才知道。`,`That night you took her father into the cannery. Beto's sixty, and he coughed for three days after. She only found out this morning.`,`Naquela noite levaste o pai dela à fábrica. O Beto tem sessenta anos e tossiu três dias. Ela só soube esta manhã.`)
  :w==='lucia'?t(`那晚她和你一起去了。她现在知道了：报告上的取样点，就在雷耶斯牧场南边那口井旁边。`,`She went with you that night. Now she knows: one of the sample points in the report is right beside the south well on the Reyes ranch.`,`Ela foi contigo nessa noite. Agora sabe: um dos pontos de recolha do relatório fica mesmo ao lado do poço do sul do Rancho Reyes.`)
  :t(`那晚你没叫她。她是从别人嘴里听说你去了罐头厂的。`,`You didn't ask her along that night. She heard about the cannery from somebody else.`,`Nessa noite não a chamaste. Soube da fábrica pela boca de outra pessoa.`);
 return {title:t('一罐井水','A jar of well water','Um frasco de água do poço'),meta:rE_CM('lucia'),text:[why,
  t(`她把一罐发黄的南井水放在你的砧板上，就像当初扔下那扇牛胸肉。`,`She sets a jar of yellowish south-well water on your cutting board, the way she once dropped that brisket there.`,`Pousa na tua tábua um frasco de água amarelada do poço do sul, como da primeira vez atirou o peito de vaca.`),
  ...(S.flags.travisDeal==='deal'?[t(`“镇上说你在跟特拉维斯谈价钱。”她的声音很平。`,`"Town says you're cutting a deal with Travis." Her voice is flat.`,`«Dizem na vila que estás a negociar com o Travis.» A voz dela é seca.`)]:[]),
  t(`“这块地上的事，你打算怎么办？这也是我们家的事。”`,`"What are you going to do about what's under that land? It's my family's business too."`,`«O que vais fazer com o que está debaixo daquele terreno? Isto também é assunto da minha família.»`)],choices:[
  {t:t('把知道的一切摊开给她看，请她一起决定','Lay out everything you know and ask her to decide with you','Mostrar-lhe tudo o que sabes e pedir-lhe que decida contigo'),fx:()=>{addTrust('lucia',2);S.flags.rE_lucia_shared=1;log('和露西娅一起面对罐头厂的真相','Faced the cannery truth together with Lucía','Enfrentaste com a Lucía a verdade da fábrica')},next:()=>say(t('一罐井水','A jar of well water','Um frasco de água do poço'),[S.flags.evidence?t(`你把报告摊在桌上。她用兽医的眼光一行一行看数字，看完说：“好。现在是两个人的事了。”`,`You spread the report on the table. She reads the numbers line by line with a vet's eye. "Okay," she says. "Now it's two people's problem."`,`Abres o relatório em cima da mesa. Ela lê os números linha a linha, com olhos de veterinária. «Pronto», diz. «Agora é problema de dois.»`):t(`你手里没有报告，只有你记得的东西。你一样一样说给她听。她听完说：“好。现在是两个人的事了。”`,`You don't have the report, only what you remember. You tell it to her piece by piece. "Okay," she says. "Now it's two people's problem."`,`Não tens o relatório, só o que te lembras. Contas-lhe tudo, peça a peça. «Pronto», diz. «Agora é problema de dois.»`)],rE_fx(0,2))},
  {t:t('[贝托信任 5] 去牧场，三个人坐下来谈','[Beto\'s trust 5] Drive out to the ranch and sit down, all three','[Confiança do Beto 5] Ir ao rancho e sentarem-se os três'),req:()=>rel('beto').trust>=5||NEED(t('贝托信任 5','Beto\'s trust 5','confiança do Beto 5')),fx:()=>{addTrust('lucia',2);addTrust('beto',1);S.flags.rE_lucia_shared=1},next:()=>say(t('厨房桌边','The kitchen table','A mesa da cozinha'),[t(`贝托终于讲了：1998 年，若泽求他一起作证，他没敢。“我有一个八岁的女儿和一笔贷款，”他看着露西娅，“现在你二十八了。这次我不躲。”`,`Beto finally tells it: in 1998 José begged him to testify, and he didn't dare. "I had an eight-year-old and a bank loan," he says, looking at Lucía. "Now you're twenty-eight. This time I don't hide."`,`O Beto conta finalmente: em 1998 o José pediu-lhe que testemunhasse e ele não teve coragem. «Tinha uma filha de oito anos e um empréstimo», diz, a olhar para a Lucía. «Agora tens vinte e oito. Desta vez não me escondo.»`)],rE_fx(0,2))},
  {t:t('“这是我舅舅的事，我自己处理。”','"This is my uncle\'s business. I\'ll handle it."','«Isto é assunto do meu tio. Eu trato disso.»'),fx:()=>{addTrust('lucia',-2)},next:()=>say(t('一罐井水','A jar of well water','Um frasco de água do poço'),[t(`她把罐子留在砧板上，走了。“你们家的人，”她在门口说，“都爱把事藏起来。”`,`She leaves the jar on the board and goes. At the door she says, "Your family. Always hiding things."`,`Deixa o frasco na tábua e vai-se. À porta diz: «A tua família. Sempre a esconder as coisas.»`)],rE_fx(0,-2))}]}}},

/* ---------------- JOLENE ---------------- */
{id:'rE_jolene_date',when:rE_dateWhen('jolene',7,1,2),run:()=>({title:t('周一的舞台','Monday stage','Palco de segunda-feira'),meta:rE_DM('jolene'),text:[
  t(`周一孤星酒吧不营业。乔琳把钥匙在指头上转：“爷爷睡了。舞台今晚归我们。”`,`The Lone Star's closed Mondays. Jolene spins the keys on her finger. "Grandpa's asleep. Stage is ours tonight."`,`O Lone Star fecha às segundas. A Jolene faz rodar as chaves no dedo. «O avô está a dormir. Esta noite o palco é nosso.»`),
  t(`她要录一段试唱寄去纳什维尔，录了十一遍，每一遍都说“差一点”。`,`She's recording an audition tape for Nashville. Eleven takes, and every one is "almost."`,`Está a gravar uma audição para Nashville. Onze takes, e todos são «quase».`)],choices:[
  {t:t('坐在台下，当她唯一的观众','Sit in the front row, her only audience','Sentar-te na primeira fila, o único público'),fx:()=>{addLike('jolene',1);addTrust('jolene',1)},next:()=>say(t('周一的舞台','Monday stage','Palco de segunda-feira'),[t(`第十二遍她没看手机，只看着你唱。那一遍她没说“差一点”。`,`On take twelve she doesn't look at her phone, only at you. That one she doesn't call "almost."`,`No décimo segundo não olha para o telemóvel, só para ti. Esse não é «quase».`)],rE_fx(1,1))},
  {t:t('[乡愁] 上台唱一段法多','[Homesick] Get up and sing her a fado','[Saudade] Subir ao palco e cantar-lhe um fado'),req:rE_ST('saud',50),fx:()=>{addLike('jolene',2);addTrust('jolene',1);stat('saud',-5)},next:()=>say(t('周一的舞台','Monday stage','Palco de segunda-feira'),[t(`她在吉他上找到了和弦，跟着你唱，唱错了词，唱对了调。唱完你胸口轻了一点。`,`She finds the chords on her guitar and sings along — wrong words, right feeling. When it's over, your chest is a little lighter.`,`Ela encontra os acordes na guitarra e canta contigo — letra errada, sentimento certo. No fim, o peito pesa-te um pouco menos.`)],rE_fx(2,1))},
  {t:t('告诉她：第二段歌词在说谎','Tell her the second verse is lying','Dizer-lhe que a segunda estrofe está a mentir'),req:rE_T('jolene'),fx:()=>{addTrust('jolene',2);addLike('jolene',-0.5)},next:()=>say(t('周一的舞台','Monday stage','Palco de segunda-feira'),[t(`她瞪了你一分钟，然后划掉“我从不回头”，写上“我每天都回头”。“混蛋。你说得对。”`,`She glares at you for a full minute, then crosses out "I never look back" and writes "I look back every day." "Jerk. You're right."`,`Fica um minuto a fuzilar-te com os olhos, depois risca «nunca olho para trás» e escreve «olho para trás todos os dias». «Parvo. Tens razão.»`)],rE_fx(-0.5,2))}]})},
{id:'rE_jolene_crisis',when:rE_crisisWhen('jolene',21,5,2),run:()=>({title:t('劝她留下','Talk her into staying','Convencê-la a ficar'),meta:rE_CM('jolene'),text:[
  t(`厄尔从地窖梯子上摔下来，扭了腰。同一天，纳什维尔一家录音室约乔琳下周三试唱。`,`Earl falls off the cellar ladder and wrecks his back. Same day, a Nashville studio offers Jolene an audition next Wednesday.`,`O Earl cai da escada da cave e dá cabo das costas. No mesmo dia, um estúdio de Nashville oferece à Jolene uma audição na quarta-feira.`),
  t(`厄尔把你叫到一边：“劝她留下。她听你的。”`,`Earl pulls you aside. "Talk her into staying. She listens to you."`,`O Earl chama-te à parte. «Convence-a a ficar. Ela ouve-te.»`),
  t(`半夜，乔琳站在你店门口，眼睛是红的：“他让你来劝我，对吧？”`,`Past midnight Jolene's at your door, eyes red. "He told you to talk me out of it, didn't he?"`,`Passa da meia-noite, a Jolene está à tua porta, de olhos vermelhos. «Ele pediu-te para me convenceres, não foi?»`)],choices:[
  {t:t('说实话：他是让我劝，但我不劝。这周吧台我替你看','Tell the truth: he did, and you won\'t. You\'ll cover the bar this week','Dizer a verdade: pediu, e não vais. Esta semana ficas tu no bar'),fx:()=>{addTrust('jolene',2);stat('tex',2);S.flags.rE_jolene_cover=1;log('替乔琳看了一周吧台，她去了纳什维尔','Covered the bar so Jolene could go to Nashville','Ficaste no bar para a Jolene ir a Nashville')},next:()=>say(t('劝她留下','Talk her into staying','Convencê-la a ficar'),[t(`那一周你白天烤肉，晚上倒酒。第五天，厄尔推过来一杯波本：“你比若泽还犟。”`,`That week you grill by day and pour by night. On the fifth night Earl slides you a bourbon. "You're more stubborn than José."`,`Nessa semana grelhas de dia e serves copos à noite. À quinta noite o Earl empurra-te um bourbon. «És mais teimoso do que o José.»`)],rE_fx(0,2))},
  {t:t('[$150] 给她买一张去纳什维尔的巴士票，什么也不说','[$150] Buy her a bus ticket to Nashville and say nothing','[$150] Comprar-lhe um bilhete de autocarro para Nashville sem dizer nada'),req:MONEY(150),fx:()=>{S.cash-=150;addTrust('jolene',1);addLike('jolene',1)},next:()=>say(t('劝她留下','Talk her into staying','Convencê-la a ficar'),[t(`她收下了票，抱了你一下。可你看得出来，她想要的是一句话，不是一张票。`,`She takes the ticket and hugs you. But you can tell she wanted a sentence, not a ticket.`,`Ela aceita o bilhete e abraça-te. Mas percebes que queria uma frase, não um bilhete.`)],rE_fx(1,1))},
  {t:t('照厄尔说的，劝她留下','Do what Earl asked and talk her into staying','Fazer o que o Earl pediu e convencê-la a ficar'),fx:()=>{addTrust('jolene',-2)},next:()=>say(t('劝她留下','Talk her into staying','Convencê-la a ficar'),[t(`她听完，点了点头，第二天照常上班，再也没提过纳什维尔。这比吵一架更糟。`,`She hears you out, nods, shows up for her shift the next day, and never mentions Nashville again. That's worse than a fight.`,`Ouve-te até ao fim, acena, aparece no turno do dia seguinte e nunca mais fala de Nashville. É pior do que uma discussão.`)],rE_fx(0,-2))}]})},

/* ---------------- SAVANNAH ---------------- */
{id:'rE_savannah_date',when:rE_dateWhen('savannah',9,3,0),run:()=>({title:t('凌晨四点的花','Flowers at four a.m.','Flores às quatro da manhã'),meta:rE_DM('savannah'),text:[
  t(`凌晨四点，她的货车停在你店门口：“奥斯汀花市六点开门。你帮我搬货，我请你吃早饭。”`,`Four a.m. her van pulls up outside. "Austin flower market opens at six. You haul, I buy breakfast."`,`Quatro da manhã, a carrinha dela pára à tua porta. «O mercado de flores de Austin abre às seis. Tu carregas, eu pago o pequeno-almoço.»`)],choices:[
  {t:t('搬了一车的花，一句话不多说','Load a whole van of flowers without a word','Carregar uma carrinha inteira de flores sem dizer nada'),fx:()=>{addLike('savannah',1);addTrust('savannah',1)},next:()=>say(t('凌晨四点的花','Flowers at four a.m.','Flores às quatro da manhã'),[t(`回程她说：“你知道吗，安静的男人在这个州是稀有品种。”`,`On the drive back she says, "You know, a quiet man is a rare breed in this state."`,`No regresso diz: «Sabes, um homem calado é espécie rara neste estado.»`)],rE_fx(1,1))},
  {t:t('[开车] 你来开，让她在副驾上睡一会儿','[Driving] You drive; let her sleep in the passenger seat','[Condução] Conduzes tu; deixa-a dormir ao lado'),req:rE_CO('drive',1),fx:()=>{addTrust('savannah',2)},next:()=>say(t('凌晨四点的花','Flowers at four a.m.','Flores às quatro da manhã'),[t(`她靠着车窗睡着了，手里还捏着订单。醒来时已经到了圣鲁伊斯。“很久没人替我开过车了。”`,`She falls asleep against the window, the order sheet still in her hand. When she wakes they're in San Luís. "Been a long time since anybody drove for me."`,`Adormece encostada ao vidro, ainda com a lista de encomendas na mão. Acorda já em San Luís. «Há muito tempo que ninguém conduzia por mim.»`)],rE_fx(0,2))},
  {t:t('早饭时问她：你自己喜欢什么花？','Over breakfast, ask what flower she likes','Ao pequeno-almoço, perguntar-lhe de que flor gosta'),req:rE_T('savannah'),fx:()=>{addTrust('savannah',2);addLike('savannah',1);S.flags.rE_savannah_asked=1},next:()=>say(t('凌晨四点的花','Flowers at four a.m.','Flores às quatro da manhã'),[t(`她放下叉子，愣了很久。“牡丹，”她说，“德州种不活。”然后她笑了，眼睛湿了一下。`,`She puts down her fork and goes still a long time. "Peonies," she says. "They won't grow in Texas." Then she laughs, and her eyes go wet for a second.`,`Pousa o garfo e fica muito tempo parada. «Peónias», diz. «Não crescem no Texas.» Depois ri-se, e os olhos ficam molhados por um instante.`)],rE_fx(1,2))}]})},
{id:'rE_savannah_crisis',when:rE_crisisWhen('savannah',21,3,2),run:()=>({title:t('例行检查','Routine inspection','Inspeção de rotina'),meta:rE_CM('savannah'),text:[
  t(`打烊时，普鲁伊特警长来做“例行检查”，开了一张罚单，然后压低声音：“离她远点，葡萄牙小子。”`,`At closing, Sheriff Pruitt walks in for a "routine inspection," writes you a ticket, then drops his voice. "Stay away from her, Portugal."`,`À hora de fechar, o xerife Pruitt entra para uma «inspeção de rotina», passa-te uma multa e baixa a voz: «Afasta-te dela, português.»`),
  t(`你闻到他身上的酒味。昨晚特拉维斯在孤星酒吧请了他一整晚。`,`You smell whiskey on him. Last night Travis bought his drinks all evening at the Lone Star.`,`Cheiras-lhe o uísque. Ontem à noite o Travis pagou-lhe as bebidas todas no Lone Star.`)],choices:[
  {t:t('平静地签字。当晚就去花店，把一切告诉她','Sign calmly. Go to the flower shop that night and tell her everything','Assinar com calma. Ir à florista nessa noite e contar-lhe tudo'),fx:()=>{addTrust('savannah',2)},next:()=>say(t('例行检查','Routine inspection','Inspeção de rotina'),[t(`她听完，说：“你没跟他吵。”不是问句。“他最想要的，就是你跟他吵。”她把门口的灯关了，没让你走。`,`She hears it out. "You didn't fight him." It isn't a question. "That's the one thing he wanted." She switches off the porch light and doesn't send you home.`,`Ouve tudo. «Não discutiste com ele.» Não é pergunta. «Era a única coisa que ele queria.» Apaga a luz da entrada e não te manda embora.`)],rE_fx(0,2))},
  {t:t('[口碑 60] 第二天先告诉她，再去镇议会正式投诉','[Reputation 60] Tell her first, then file a formal complaint with the council','[Reputação 60] Contar-lhe primeiro e depois apresentar queixa formal à câmara'),req:()=>S.rep>=60||NEED(t('口碑 60','Reputation 60','Reputação 60')),fx:()=>{addTrust('savannah',2);S.rep+=2;S.flags.rE_savannah_complaint=1},next:()=>say(t('例行检查','Routine inspection','Inspeção de rotina'),[t(`投诉书上有你的签名，也有她的。“十二年了，”她说，“我第一次把他的名字写在纸上，而不是背在身上。”`,`The complaint has your signature on it, and hers. "Twelve years," she says, "and this is the first time I've put his name on paper instead of wearing it."`,`A queixa tem a tua assinatura e a dela. «Doze anos», diz ela, «e é a primeira vez que ponho o nome dele num papel em vez de o carregar.»`)],rE_fx(0,2))},
  {t:t('冲警长回嘴，让他当众难堪','Mouth off and humiliate the sheriff','Responder torto ao xerife e humilhá-lo'),fx:()=>{addTrust('savannah',-2);S.rep-=3},next:()=>say(t('例行检查','Routine inspection','Inspeção de rotina'),[t(`那句话第二天传遍了主街。萨凡纳站在花店门口看着你：“你跟他一样，把我当成一场比赛。”`,`By morning the line is all over Main Street. Savannah stands in her doorway and looks at you. "You're just like him. I'm a contest to you."`,`De manhã a frase já correu a rua principal. A Savannah, à porta da loja, olha para ti. «És igual a ele. Para ti sou uma competição.»`)],rE_fx(0,-2))}]})},

/* ---------------- CLARA ---------------- */
{id:'rE_clara_date',when:rE_dateWhen('clara',8,4,2),run:()=>({title:t('七十个名字','Seventy names','Setenta nomes'),meta:rE_DM('clara'),text:[
  t(`图书馆九点关门。克拉拉没有锁门，只关了一半的灯。`,`The library closes at nine. Clara doesn't lock up; she just turns off half the lights.`,`A biblioteca fecha às nove. A Clara não tranca a porta; só apaga metade das luzes.`),
  t(`“佩索阿有七十多个化名，”她说，“今晚我们一人选一个，用他的名字说话。”`,`"Pessoa had over seventy heteronyms," she says. "Tonight we each pick one and talk as him."`,`«O Pessoa teve mais de setenta heterónimos», diz ela. «Esta noite cada um escolhe um e fala como ele.»`)],choices:[
  {t:t('当冈波斯，大声念《烟草店》','Be Campos and read "The Tobacco Shop" aloud','Ser o Campos e ler «Tabacaria» em voz alta'),fx:()=>{addLike('clara',1);stat('saud',2)},next:()=>say(t('七十个名字','Seventy names','Setenta nomes'),[t(`你念到“我心里有世上所有的梦”时，保洁员推着车停在门口听完了。`,`When you reach "I have in me all the dreams of the world," the janitor stops his cart in the doorway and listens to the end.`,`Quando chegas a «Tenho em mim todos os sonhos do mundo», o empregado da limpeza pára o carrinho à porta e ouve até ao fim.`)],rE_fx(1,0))},
  {t:t('[乡愁] 用原文念里斯本的街名，从你家门口一直走到河边','[Homesick] Recite Lisbon street names, from your front door to the river','[Saudade] Dizer os nomes das ruas de Lisboa, da tua porta até ao rio'),req:rE_ST('saud',55),fx:()=>{addLike('clara',2);addTrust('clara',1);stat('saud',3)},next:()=>say(t('七十个名字','Seventy names','Setenta nomes'),[t(`她闭着眼，跟着你“走”。到了河边，她说：“我闻到了。”你没告诉她，你也闻到了。`,`She closes her eyes and walks it with you. When you reach the river she says, "I can smell it." You don't tell her you can too.`,`Ela fecha os olhos e caminha contigo. Quando chegam ao rio, diz: «Consigo sentir o cheiro.» Não lhe dizes que tu também.`)],rE_fx(2,1))},
  {t:t('不用化名，用你自己的名字说一件从没告诉别人的事','No heteronym: tell her something you\'ve never told anyone, as yourself','Sem heterónimo: contar-lhe, como tu próprio, uma coisa que nunca contaste'),req:rE_T('clara'),fx:()=>{addTrust('clara',2)},next:()=>say(t('七十个名字','Seventy names','Setenta nomes'),[t(`你说你离开里斯本的前一晚，没有跟妈妈道别。克拉拉什么都没说，只是把台灯往你这边推了推。`,`You tell her that the night before you left Lisbon, you didn't say goodbye to your mother. Clara says nothing; she just slides the desk lamp a little toward you.`,`Contas-lhe que na noite antes de saíres de Lisboa não te despediste da tua mãe. A Clara não diz nada; só empurra o candeeiro um pouco para o teu lado.`)],rE_fx(0,2))}]})},
{id:'rE_clara_crisis',when:rE_crisisWhen('clara',26,4,0),run:()=>({title:t('一张清单','A list','Uma lista'),meta:rE_CM('clara'),text:[
  t(`克拉拉拿到了去里斯本国家图书馆两个月的研究金。她请你帮她列一张“必须去的地方”。`,`Clara has won two months at the National Library in Lisbon. She asks you to write her a list of places she has to go.`,`A Clara ganhou dois meses na Biblioteca Nacional, em Lisboa. Pede-te uma lista de sítios obrigatórios.`),
  ...(rel('ines').met?[t(`写到一半她停了。她见过你和伊内丝说葡语。“那时候你像另一个人，我听不懂的那个。”`,`Halfway through she stops. She's seen you and Inês talking Portuguese. "Then you're someone else. Someone I can't understand."`,`A meio pára. Já te viu a falar português com a Inês. «Aí és outra pessoa. Uma que eu não percebo.»`)]:[]),
  t(`“我是不是只因为你是里斯本才喜欢你？”她问，“你是不是只因为我喜欢里斯本才喜欢我？”`,`"Do I only like you because you're Lisbon?" she asks. "Do you only like me because I like Lisbon?"`,`«Será que só gosto de ti porque és Lisboa?», pergunta. «Será que só gostas de mim porque eu gosto de Lisboa?»`)],choices:[
  {t:t('承认两个问题你都不确定，但你想知道答案——不在书里','Admit you don\'t know either answer, but you want to find out — not in a book','Admitir que não sabes nenhuma das respostas, mas queres descobrir — fora dos livros'),fx:()=>{addTrust('clara',2)},next:()=>say(t('一张清单','A list','Uma lista'),[t(`她把清单翻过来，在背面写：“第一个地方：圣鲁伊斯，主街，若泽烧烤店。”`,`She turns the list over and writes on the back: "First place: San Luís, Main Street, Zé's Churrasco."`,`Vira a lista e escreve no verso: «Primeiro sítio: San Luís, rua principal, Zé's Churrasco.»`)],rE_fx(0,2))},
  {t:t('[德州味] 告诉她你最喜欢的，是她给牛仔讲佩索阿的样子','[Texan] Tell her what you love most is her explaining Pessoa to cowboys','[Texano] Dizer-lhe que o que mais gostas é de a ver explicar Pessoa a vaqueiros'),req:rE_ST('tex',40),fx:()=>{addTrust('clara',2);addLike('clara',1)},next:()=>say(t('一张清单','A list','Uma lista'),[t(`“那不是里斯本，”你说，“那是你。是圣鲁伊斯的你。”她笑出声，第一次没有用手捂着嘴。`,`"That's not Lisbon," you say. "That's you. The San Luís you." She laughs out loud, and for once she doesn't cover her mouth.`,`«Isso não é Lisboa», dizes. «És tu. A tu de San Luís.» Ela ri alto e, pela primeira vez, não tapa a boca.`)],rE_fx(1,2))},
  {t:t('把清单写得满满的，绕开那个问题','Fill the list to the edges and skip the question','Encher a lista até às margens e fugir à pergunta'),fx:()=>{addTrust('clara',-2)},next:()=>say(t('一张清单','A list','Uma lista'),[t(`她收下清单，客气地道谢，像接过一本逾期的书。`,`She takes the list and thanks you politely, the way she'd accept an overdue book.`,`Aceita a lista e agradece com delicadeza, como quem recebe um livro fora de prazo.`)],rE_fx(0,-2))}]})},

/* ---------------- HANNAH ---------------- */
{id:'rE_hannah_date',when:rE_dateWhen('hannah',10,2,2),run:()=>({title:t('夜间出诊','House call','Visita ao domicílio'),meta:rE_DM('hannah'),text:[
  t(`晚上九点汉娜打来电话：“镇东有个老太太发烧，家里没大人。我需要个人帮我打手电。”`,`Nine p.m., Hannah calls. "Old lady with a fever east of town, no grown-ups home. I need somebody to hold a flashlight."`,`Nove da noite, a Hannah liga. «Uma senhora com febre a leste da vila, sem adultos em casa. Preciso de alguém que segure a lanterna.»`),
  t(`回来的路上，她停在空公路边，点了一根“不算数”的烟。星星多得不讲道理。`,`On the way back she pulls over on the empty highway and lights a cigarette that "doesn't count." The stars are unreasonable.`,`No regresso encosta na estrada vazia e acende um dos cigarros que «não contam». As estrelas lá em cima são um exagero.`)],choices:[
  {t:t('陪她安静地看星星','Watch the stars with her in silence','Ver as estrelas com ela, em silêncio'),fx:()=>{addTrust('hannah',1);addLike('hannah',1)},next:()=>say(t('夜间出诊','House call','Visita ao domicílio'),[t(`过了很久，她说：“明尼苏达的星星也这么多。只是太冷，没人抬头。”`,`After a long time she says, "Minnesota has this many stars too. It's just too cold for anybody to look up."`,`Muito depois diz: «No Minnesota também há tantas estrelas. Só que está frio demais para alguém olhar para cima.»`)],rE_fx(1,1))},
  {t:t('[手艺] 在老太太家的厨房给全家煮一锅汤','[Craft] Cook the whole family a pot of soup in the old lady\'s kitchen','[Ofício] Fazer uma panela de sopa para a família na cozinha da senhora'),req:rE_ST('oficio',40),fx:()=>{addLike('hannah',1);addTrust('hannah',1);S.rep+=2},next:()=>say(t('夜间出诊','House call','Visita ao domicílio'),[t(`你在冰箱里找到两根胡萝卜和半只鸡。汉娜在病历上写：“处方：汤。开方人：不是我。”`,`You find two carrots and half a chicken in the fridge. On the chart Hannah writes: "Prescription: soup. Prescribed by: not me."`,`Encontras duas cenouras e meio frango no frigorífico. Na ficha a Hannah escreve: «Receita: sopa. Receitado por: não fui eu.»`)],rE_fx(1,1))},
  {t:t('把她的烟拿过来掐灭：“它算数。你也算数。”','Take her cigarette and put it out: "It counts. So do you."','Tirar-lhe o cigarro e apagá-lo: «Conta. E tu também contas.»'),req:rE_T('hannah'),fx:()=>{addTrust('hannah',2);addLike('hannah',1)},next:()=>say(t('夜间出诊','House call','Visita ao domicílio'),[t(`她看着烟头，像看一张早知结果的化验单。“好吧。那这是最后一根。”`,`She looks at the stub like a lab result she already knew. "Fine. Then that was the last one."`,`Olha para a beata como para uma análise cujo resultado já sabia. «Está bem. Então foi o último.»`)],rE_fx(1,2))}]})},
{id:'rE_hannah_crisis',when:rE_crisisWhen('hannah',32,1,2),run:()=>({title:t('越界','Overstepping','Passar dos limites'),meta:rE_CM('hannah'),text:[
  t(`鲁伊打来电话：汉娜医生昨晚跟妈妈的主治医生通了四十分钟电话，最坏的先问。`,`Rui calls: last night Dr. Hannah spent forty minutes on the phone with Mother's doctor in Lisbon, worst questions first.`,`O Rui liga: ontem à noite a Dra. Hannah esteve quarenta minutos ao telefone com o médico da mãe em Lisboa, o pior primeiro.`),
  t(`你冲进诊所。她在写病历，没抬头：“我知道我越界了。我也知道你永远不会开口求我。”`,`You storm into the clinic. She's writing charts and doesn't look up. "I know I overstepped. I also know you'd never ask me."`,`Entras no consultório de rompante. Ela está a escrever fichas e não levanta os olhos. «Sei que passei dos limites. Também sei que nunca me pedirias.»`)],choices:[
  {t:t('坐下，谢谢她，然后问：最坏的情况是什么？','Sit down, thank her, and ask: what\'s the worst case?','Sentar-te, agradecer-lhe e perguntar: qual é o pior cenário?'),fx:()=>{addTrust('hannah',2);stat('saud',3)},next:()=>say(t('越界','Overstepping','Passar dos limites'),[t(`她说得很慢。你第一次在她面前哭了。她没递纸巾，只是按住你的手腕，数你的脉。`,`She tells you, slowly. You cry in front of her for the first time. She doesn't hand you a tissue; she just puts two fingers on your wrist and counts your pulse.`,`Ela diz-te, devagar. Choras à frente dela pela primeira vez. Não te dá um lenço; só te põe dois dedos no pulso e conta-te as pulsações.`)],rE_fx(0,2))},
  {t:t('[乡愁] 请她下次通话时叫上你，你来翻译那些她不会的葡语','[Homesick] Ask her to include you next call, so you can translate the Portuguese she can\'t','[Saudade] Pedir-lhe que te chame na próxima chamada, para traduzires o português que ela não sabe'),req:rE_ST('saud',60),fx:()=>{addTrust('hannah',2);addLike('hannah',1);S.flags.rE_hannah_mom=1;log('和汉娜一起给妈妈的医生打了电话','Called Mother\'s doctor together with Hannah','Ligaste com a Hannah ao médico da tua mãe')},next:()=>say(t('越界','Overstepping','Passar dos limites'),[t(`第二次通话妈妈也在。她听不懂汉娜的英语，却听懂了语气：“这个医生，你别让她跑了。”`,`On the second call Mother is on the line too. She can't follow Hannah's English, but she follows her tone. "This doctor — don't let her get away."`,`Na segunda chamada a mãe também está em linha. Não percebe o inglês da Hannah, mas percebe-lhe o tom. «Essa médica, não a deixes fugir.»`)],rE_fx(1,2))},
  {t:t('冲她发火：“那是我妈，不是你的病人。”','Snap at her: "That\'s my mother, not your patient."','Explodir: «É a minha mãe, não é tua doente.»'),fx:()=>{addTrust('hannah',-2)},next:()=>say(t('越界','Overstepping','Passar dos limites'),[t(`她说了声“对不起”，从此再也不问你母亲的事。后来你才明白，那比越界更难受。`,`She says she's sorry, and never asks about your mother again. Later you understand that's worse than any overstep.`,`Ela pede desculpa e nunca mais pergunta pela tua mãe. Mais tarde percebes que isso é pior do que passar qualquer limite.`)],rE_fx(0,-2))}]})},

/* ---------------- BROOKE ---------------- */
{id:'rE_brooke_date',when:rE_dateWhen('brooke',10,6,1),run:()=>({title:t('县城竞技场','County rodeo','Rodeio do condado'),meta:rE_DM('brooke'),text:[
  t(`贝尔顿周六有县级牛仔竞技。布鲁克把一顶旧帽子扣在你头上：“今天你是我的马夫。”`,`There's a county rodeo in Belton on Saturday. Brooke jams an old hat on your head. "Today you're my groom."`,`Há um rodeio do condado em Belton no sábado. A Brooke enfia-te um chapéu velho na cabeça. «Hoje és o meu tratador.»`)],choices:[
  {t:t('在看台上喊她的名字，喊得比谁都响','Yell her name from the stands louder than anybody','Gritar o nome dela da bancada mais alto do que todos'),fx:()=>{addLike('brooke',1);stat('tex',3)},next:()=>say(t('县城竞技场','County rodeo','Rodeio do condado'),[t(`她拿了第三名。下场时她指着你对裁判说：“那个吵的是我的。”`,`She takes third. Riding out she points at you and tells the judge, "The loud one's mine."`,`Fica em terceiro. À saída aponta para ti e diz ao juiz: «O barulhento é meu.»`)],rE_fx(1,0))},
  {t:t('[骑马] 报名业余组的绕桶赛','[Riding] Enter the amateur barrel race','[Equitação] Inscrever-te na prova amadora de barris'),req:rE_CO('ride',2),fx:()=>{addLike('brooke',2);addTrust('brooke',1);stat('tex',4)},next:()=>say(t('县城竞技场','County rodeo','Rodeio do condado'),[t(`你撞倒了第二个桶，但没掉下来。她在围栏外笑得蹲在地上，跟那天在牧场一模一样。`,`You knock over the second barrel but stay on. Outside the rail she laughs until she's crouched in the dirt, same as that day on the ranch.`,`Derrubas o segundo barril mas não cais. Do lado de fora da vedação ela ri-se até se agachar no chão, tal como naquele dia no rancho.`)],rE_fx(2,1))},
  {t:t('赛后问她：下一站之前，你想做什么？','After, ask her: before the next stop, what do you want to do?','No fim, perguntar-lhe: antes da próxima paragem, o que queres fazer?'),req:rE_T('brooke'),fx:()=>{addTrust('brooke',2);addLike('brooke',1)},next:()=>say(t('县城竞技场','County rodeo','Rodeio do condado'),[t(`她想了很久：“吃一顿不在车里吃的饭。”你带她回店里烤了一只最慢的鸡，她等了一小时，一次也没看表。`,`She thinks a long time. "Eat a meal that isn't in the truck." You take her back to the restaurant and make the slowest grilled chicken of your life. She waits an hour and never once checks the time.`,`Pensa muito tempo. «Comer uma refeição que não seja na carrinha.» Levas-la ao restaurante e fazes o frango assado mais lento da tua vida. Ela espera uma hora sem olhar uma única vez para o relógio.`)],rE_fx(1,2))}]})},
{id:'rE_brooke_crisis',when:rE_crisisWhen('brooke',21,6,2),run:()=>({title:t('凌晨两点的电话','The 2 a.m. call','A chamada das duas da manhã'),meta:rE_CM('brooke'),text:[
  t(`凌晨两点，布鲁克从沃斯堡的急诊室打来电话。葡萄干在第三个桶前失了前蹄，她摔断了两根肋骨。`,`Two a.m., Brooke calls from an emergency room in Fort Worth. Raisin stumbled at the third barrel and she cracked two ribs.`,`Duas da manhã, a Brooke liga de umas urgências em Fort Worth. O Passa tropeçou no terceiro barril e ela partiu duas costelas.`),
  t(`“医生让我休三个月。我明天就开车去下一站。”她的声音在笑，手在抖。“别劝我。”`,`"Doc says three months off. I'm driving to the next stop tomorrow." Her voice is laughing; you can hear her hand shaking. "Don't you dare talk me out of it."`,`«O médico diz três meses de paragem. Amanhã sigo para a próxima prova.» A voz ri-se; ouves-lhe a mão a tremer. «Nem penses em convencer-me.»`)],choices:[
  {t:t('[开车] 连夜开去沃斯堡，不劝她，只把她接回来养伤','[Driving] Drive to Fort Worth overnight — don\'t argue, just bring her home to heal','[Condução] Conduzir de noite até Fort Worth — sem discutir, só trazê-la para recuperar'),req:rE_CO('drive',2),fx:()=>{addTrust('brooke',2);S.flags.rE_brooke_home=1;log('把受伤的布鲁克接回了圣鲁伊斯','Brought an injured Brooke home to San Luís','Trouxeste a Brooke ferida para San Luís')},next:()=>say(t('凌晨两点的电话','The 2 a.m. call','A chamada das duas da manhã'),[t(`天亮时你到了。她上车只说：“就三个星期。”她在你楼上的小房间里躺了六个星期。`,`You get there at dawn. In the truck all she says is "Three weeks. That's all." She stays six weeks in your little room upstairs.`,`Chegas ao amanhecer. No carro ela só diz: «Três semanas. Mais nada.» Fica seis semanas no teu quartinho lá em cima.`)],rE_fx(0,2))},
  {t:t('[韦德信任 4] 请韦德开车，一起去接她和她的马','[Wade\'s trust 4] Ask Wade to drive; go get her and the horse together','[Confiança do Wade 4] Pedir ao Wade que conduza; irem buscá-la e ao cavalo'),req:()=>rel('wade').trust>=4||NEED(t('韦德信任 4','Wade\'s trust 4','confiança do Wade 4')),fx:()=>{addTrust('brooke',2);addTrust('wade',1);S.flags.rE_brooke_home=1},next:()=>say(t('凌晨两点的电话','The 2 a.m. call','A chamada das duas da manhã'),[t(`韦德一路没说话，到了马厩只检查了葡萄干的蹄子：“马没事。是骑手需要歇。”布鲁克没有顶嘴。`,`Wade doesn't say a word the whole drive. At the stable he checks Raisin's hooves and says, "Horse is fine. It's the rider needs rest." Brooke doesn't argue.`,`O Wade não diz uma palavra a viagem toda. No estábulo examina os cascos do Passa e diz: «O cavalo está bem. Quem precisa de descanso é a cavaleira.» A Brooke não refila.`)],rE_fx(0,2))},
  {t:t('在电话里说：“你该停下来了。这就是信号。”','Tell her on the phone: "You need to stop. This is the sign."','Dizer-lhe ao telefone: «Tens de parar. É um sinal.»'),fx:()=>{addTrust('brooke',-2)},next:()=>say(t('凌晨两点的电话','The 2 a.m. call','A chamada das duas da manhã'),[t(`她挂了电话。三天后，她的名字出现在俄克拉荷马的出场名单上。`,`She hangs up. Three days later her name shows up on a start list in Oklahoma.`,`Ela desliga. Três dias depois o nome dela aparece numa lista de partida em Oklahoma.`)],rE_fx(0,-2))}]})},

/* ---------------- MEGAN ---------------- */
{id:'rE_megan_date',when:rE_dateWhen('megan',8,7,2),run:()=>({title:t('免下车汉堡店','The drive-in','O drive-in'),meta:rE_DM('megan'),text:[
  t(`晚祷后，梅根把她爸的旧车开到镇外一家免下车汉堡店：“在这儿，没人认识牧师的女儿。”`,`After evening service Megan drives her daddy's old sedan to a drive-in outside town. "Out here nobody knows the pastor's daughter."`,`Depois do culto da noite a Megan leva o carro velho do pai a um drive-in fora da vila. «Aqui ninguém conhece a filha do pastor.»`)],choices:[
  {t:t('让她点菜单上最不像牧师女儿会点的东西','Dare her to order the least pastor\'s-daughter thing on the menu','Desafiá-la a pedir a coisa menos própria de filha de pastor'),fx:()=>{addLike('megan',1);stat('tex',2)},next:()=>say(t('免下车汉堡店','The drive-in','O drive-in'),[t(`她点了一杯巨大的奶昔和双份洋葱圈，然后笑到被呛。“这是我这辈子干过最坏的事。”`,`She orders an enormous milkshake and double onion rings and laughs so hard she chokes. "That's the worst thing I've ever done."`,`Pede um batido enorme e anéis de cebola a dobrar, e ri-se tanto que se engasga. «É a pior coisa que já fiz na vida.»`)],rE_fx(1,0))},
  {t:t('问她休斯敦那所音乐学院，现在还想不想去','Ask about the Houston conservatory — does she still want it?','Perguntar pelo conservatório de Houston — ainda o quer?'),req:rE_T('megan'),fx:()=>{addTrust('megan',2);S.flags.rE_megan_houston=1},next:()=>say(t('免下车汉堡店','The drive-in','O drive-in'),[t(`她盯着方向盘：“他们去年又寄了信，我一直没拆。”她把信从手套箱里拿出来，放在你手里。“你拆。”`,`She stares at the wheel. "They wrote me again last year. I never opened it." She takes the envelope out of the glove box and puts it in your hand. "You open it."`,`Olha para o volante. «Voltaram a escrever-me no ano passado. Nunca abri.» Tira o envelope do porta-luvas e põe-to na mão. «Abre tu.»`)],rE_fx(0,2))},
  {t:`[${faceWord()}] `+t('在停车场里吻她','Kiss her in the parking lot','Beijá-la no parque de estacionamento'),req:CHARM_REQ(55),fx:()=>{addLike('megan',2);flirt();S.flags.rE_megan_seen=1},next:()=>say(t('免下车汉堡店','The drive-in','O drive-in'),[t(`她没有躲。可车窗外，一辆熟悉的皮卡慢慢开过去——是唱诗班女高音的丈夫。`,`She doesn't pull away. But outside the window a familiar pickup rolls slowly by — the choir soprano's husband.`,`Ela não se afasta. Mas lá fora passa devagar uma carrinha conhecida — o marido da soprano do coro.`)],rE_fx(2,0))}]})},
{id:'rE_megan_crisis',when:rE_crisisWhen('megan',21,7,1),run:()=>({title:t('周日的讲道','Sunday sermon','O sermão de domingo'),meta:rE_CM('megan'),text:[
  S.flags.license?t(`酒类执照批下来以后，戴尔牧师的讲道一周比一周长。`,`Ever since the liquor license went through, Pastor Dale's sermons have gotten longer every week.`,`Desde que a licença de álcool foi aprovada, os sermões do Pastor Dale ficam mais compridos todas as semanas.`):t(`酒类执照没批下来，可流言一点也没停。`,`The liquor license was turned down, but the talk hasn't stopped one bit.`,`A licença de álcool foi recusada, mas o falatório não parou nada.`),
  ...(S.flags.rE_megan_seen?[t(`有人看见了汉堡店停车场的事，现在全教堂都知道了。`,`Somebody saw what happened in that drive-in parking lot, and now the whole congregation knows.`,`Alguém viu o que se passou no parque do drive-in, e agora a congregação inteira sabe.`)]:[]),
  t(`今天他讲“城门口带烈酒的陌生人”，全教堂都在看梅根。散会后她说：“他说的是你，也是我。下午我去他书房回答他。你来吗？”`,`Today it's "the stranger at the gate who brings strong drink." The whole church is looking at Megan. Afterward she says, "He meant you. And me. I'm going to his study this afternoon to answer him. Are you coming?"`,`Hoje o tema é «o estrangeiro à porta que traz bebida forte». A igreja inteira olha para a Megan. No fim diz-te: «Falava de ti. E de mim. Esta tarde vou ao escritório dele responder-lhe. Vens?»`)],choices:[
  {t:t('[正式场合] 一起去，用最清楚的英语说你尊重他，但不会躲','[Formal] Go together and say, in your clearest English, that you respect him but won\'t hide','[Formal] Irem juntos e dizer, no teu inglês mais claro, que o respeitas mas não te vais esconder'),req:()=>charm()+formalPenalty()>=50||NEED(t('正式场合魅力 50','Formal charm 50','Charme formal 50')),fx:()=>{addTrust('megan',2);addTrust('dale',1);log('在戴尔牧师书房里站在梅根身边','Stood by Megan in Pastor Dale\'s study','Ficaste ao lado da Megan no escritório do Pastor Dale')},next:()=>say(t('周日的讲道','Sunday sermon','O sermão de domingo'),[t(`牧师听完，摘下眼镜擦了很久。“你说话像个推销员，”他说，“可你没有低头。这一点我记下了。”`,`The pastor hears you out, then takes off his glasses and cleans them a long time. "You talk like a salesman," he says. "But you didn't look at the floor. I'll give you that."`,`O pastor ouve-te até ao fim, tira os óculos e limpa-os muito tempo. «Falas como um vendedor», diz. «Mas não olhaste para o chão. Isso reconheço.»`)],rE_fx(0,2))},
  {t:t('一起去，但让她说。你只站在她旁边','Go with her, but let her speak. You just stand beside her','Ir com ela, mas deixá-la falar. Ficas só ao lado dela'),fx:()=>{addTrust('megan',2);addLike('megan',1)},next:()=>say(t('周日的讲道','Sunday sermon','O sermão de domingo'),[t(`她讲了二十分钟，你一句没插。出来时她腿还在发软：“我这辈子第一次在他面前把话说完。”`,`She talks for twenty minutes and you don't say a word. Outside, her knees are still weak. "First time in my life I finished a sentence in front of him."`,`Ela fala vinte minutos e tu não dizes nada. Lá fora ainda tem as pernas a tremer. «Foi a primeira vez na vida que acabei uma frase à frente dele.»`)],rE_fx(1,2))},
  {t:t('“我们先别见面了，等风头过去。”','"Let\'s not see each other for a while. Let it blow over."','«É melhor não nos vermos durante uns tempos. Até isto acalmar.»'),fx:()=>{addTrust('megan',-2)},next:()=>say(t('周日的讲道','Sunday sermon','O sermão de domingo'),[t(`她点点头。“我这辈子都站在别人看得见的地方，”她说，“我以为你会站过来。”`,`She nods. "I've stood where everybody could see me my whole life," she says. "I thought you'd come stand with me."`,`Ela acena. «Passei a vida inteira onde toda a gente me via», diz. «Pensei que vinhas pôr-te ao meu lado.»`)],rE_fx(0,-2))}]})},

/* ---------------- COLLEEN ---------------- */
{id:'rE_colleen_date',when:rE_dateWhen('colleen',9,4,1),run:()=>({title:t('下印日','Press day','Dia de impressão'),meta:rE_DM('colleen'),text:[
  t(`周四中午，《号角报》下印。科琳把你拉进印刷间：“每周就这一个小时，我觉得自己是个真正的记者。”`,`Thursday noon, the Clarion goes to press. Colleen pulls you into the press room. "One hour a week, I feel like a real reporter."`,`Quinta ao meio-dia, o Clarion vai para a gráfica. A Colleen puxa-te para a sala das rotativas. «Uma hora por semana, sinto-me uma jornalista a sério.»`)],choices:[
  {t:t('帮她校对头版：“县集市南瓜冠军”','Help proofread the front page: "County Fair Pumpkin Champion"','Ajudar a rever a primeira página: «Campeão da Abóbora da Feira do Condado»'),fx:()=>{addLike('colleen',1);stat('tex',2)},next:()=>say(t('下印日','Press day','Dia de impressão'),[t(`你找出了三个错字，其中一个是冠军的名字。她说：“你救了一个家族的荣誉。”`,`You catch three typos, one of them the champion's name. "You just saved a family's honor," she says.`,`Encontras três gralhas, uma delas no nome do campeão. «Acabaste de salvar a honra de uma família», diz ela.`)],rE_fx(1,0))},
  {t:t('告诉她若泽信里关于罐头厂的一段','Tell her what José wrote about the cannery','Contar-lhe o que o José escreveu sobre a fábrica'),req:rE_T('colleen'),fx:()=>{addTrust('colleen',2);S.flags.rE_colleen_tip=1;log('把若泽信里的罐头厂往事告诉了科琳','Told Colleen what José\'s letters say about the cannery','Contaste à Colleen o que as cartas do José dizem da fábrica')},next:()=>say(t('下印日','Press day','Dia de impressão'),[t(`她第一次没有记笔记。印刷机停了，她才说：“我祖父也写过这样的信。也没寄。”`,`For the first time, she doesn't take notes. When the press stops, she says, "My grandpa wrote letters like that too. Never sent them either."`,`Pela primeira vez, não toma notas. Quando a rotativa pára, diz: «O meu avô também escreveu cartas assim. Também nunca as mandou.»`)],rE_fx(0,2))},
  {t:t('[魅力] 让她采访你——这次不许问口音','[Charm] Let her interview you — no accent questions this time','[Charme] Deixá-la entrevistar-te — desta vez sem perguntas sobre o sotaque'),req:CHARM_REQ(50),fx:()=>{addLike('colleen',1);S.rep+=2},next:()=>say(t('下印日','Press day','Dia de impressão'),[t(`你讲得很好，好到她合上本子：“这段太好了，不能用。读者会以为我被你收买了。”`,`You're good — so good she shuts her notebook. "That's too good to print. Readers'll think you bought me."`,`Estás tão bem que ela fecha o caderno. «Isto está bom demais para publicar. Os leitores vão achar que me compraste.»`)],rE_fx(1,0))}]})},
{id:'rE_colleen_crisis',when:rE_crisisWhen('colleen',22,2,0),run:()=>({title:t('头版','Front page','Primeira página'),meta:rE_CM('colleen'),text:[
  t(`早上的《号角报》登了关于你的报道。最后一段写着：1998 年若泽被罐头厂解雇后，“据知情人士称，曾与厂方签署一份和解协议”。`,`This morning's Clarion runs the story about you. The last paragraph says that after José was fired from the cannery in 1998, "according to a source, he signed a settlement agreement with the company."`,`O Clarion desta manhã publica a reportagem sobre ti. O último parágrafo diz que, depois de o José ter sido despedido da fábrica em 1998, «segundo uma fonte, assinou um acordo com a empresa».`),
  S.flags.rE_colleen_tip?t(`那段话，是你在印刷间里告诉她的。`,`That paragraph is what you told her in the press room.`,`Esse parágrafo é o que lhe contaste na sala das rotativas.`):t(`那段话来自她祖父——在疗养院里，他对着录音笔讲了四十分钟。`,`It came from her grandfather — forty minutes into a voice recorder at the nursing home.`,`Veio do avô dela — quarenta minutos para um gravador, no lar.`),
  t(`七点，科琳攥着报纸站在你门口：“我该先问你的。我怕你说不。”十点，特拉维斯打来电话：“听说你手里有份老文件？”`,`At seven Colleen is at your door, the paper in her fist. "I should've asked you first. I was scared you'd say no." At ten Travis calls: "Hear you've got some old paperwork?"`,`Às sete a Colleen está à tua porta, com o jornal na mão. «Devia ter-te perguntado primeiro. Tive medo que dissesses que não.» Às dez o Travis liga: «Ouvi dizer que tens uns papéis antigos?»`)],choices:[
  {t:t('让她进来，倒杯咖啡：“那接下来我们怎么办？”','Let her in, pour her a coffee: "So what do we do next?"','Deixá-la entrar, servir-lhe um café: «E agora, o que fazemos?»'),fx:()=>{addTrust('colleen',2);S.flags.rE_colleen_team=1;log('和科琳结成了同盟','Teamed up with Colleen','Aliaste-te à Colleen')},next:()=>say(t('头版','Front page','Primeira página'),[t(`她在你的柜台上摊开笔记本，写下第一行：“不要相信任何人——”然后划掉“任何人”，改成“特拉维斯”。`,`She opens her notebook on your counter and writes the first line: "Don't trust anybody —" then crosses out "anybody" and writes "Travis."`,`Abre o caderno no teu balcão e escreve a primeira linha: «Não confies em ninguém —» depois risca «ninguém» e escreve «Travis».`)],rE_fx(0,2))},
  {t:t('[口碑 55] 把报道贴在店门上，让全镇知道你不怕','[Reputation 55] Tape the article to your front door and let the town see you\'re not scared','[Reputação 55] Colar a reportagem na porta e mostrar à vila que não tens medo'),req:()=>S.rep>=55||NEED(t('口碑 55','Reputation 55','Reputação 55')),fx:()=>{addTrust('colleen',2);S.rep+=3},next:()=>say(t('头版','Front page','Primeira página'),[t(`午饭的客人多了一倍，一半是来看报纸的。科琳在街对面拍了张照片，下周登在第二版。`,`Twice the usual lunch crowd shows up, half of them to read the clipping. Colleen takes a photo from across the street; it runs on page two the next week.`,`Ao almoço aparece o dobro das pessoas, metade para ler o recorte. A Colleen tira uma fotografia do outro lado da rua; sai na página dois na semana seguinte.`)],rE_fx(0,2))},
  {t:t('“你跟特拉维斯一样，只想要那块地底下的东西。”','"You\'re just like Travis. All you want is what\'s under that land."','«És igual ao Travis. Só queres o que está debaixo daquele terreno.»'),fx:()=>{addTrust('colleen',-2)},next:()=>say(t('头版','Front page','Primeira página'),[t(`她把报纸放在门口的台阶上，走了。下一期，她的名字不在任何一篇报道上。`,`She lays the paper on your step and walks off. Next week her byline isn't on a single story.`,`Deixa o jornal no degrau e vai-se embora. Na semana seguinte o nome dela não aparece em nenhuma peça.`)],rE_fx(0,-2))}]})}
);
